"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface CopyPlusIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface CopyPlusIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const CopyPlusIcon = forwardRef<CopyPlusIconHandle, CopyPlusIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const backVariants: Variants = {
   normal: { x: 0, y: 0 },
   animate: {
    x: [0, -1.5, 0],
    y: [0, -1.5, 0],
    transition: { duration: 0.5 * duration, ease: "easeInOut" },
   },
  };

  const signVariants: Variants = {
   normal: { scale: 1, opacity: 1, rotate: 0 },
   animate: {
    scale: [0, 1.2, 1],
    opacity: [0, 1, 1],
    rotate: [-90, 0, 0],
    transition: {
     duration: 0.45 * duration,
     ease: "easeOut",
     times: [0, 0.6, 1],
     delay: 0.15 * duration,
    },
   },
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.g
       variants={signVariants}
       style={{ transformBox: "view-box", originX: "15px", originY: "15px" }}
      >
       <line x1="15" x2="15" y1="12" y2="18" />
       <line x1="12" x2="18" y1="15" y2="15" />
      </m.g>
      <rect width="14" height="14" x="8" y="8" rx="2" ry="2" />
      <m.path
       d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"
       variants={backVariants}
      />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

CopyPlusIcon.displayName = "CopyPlusIcon";
export { CopyPlusIcon };
